import React from 'react';
import whats from './logos/whats.png';
import insta from './logos/insta.png';
import contact from './logos/contact.png';

const Footer = ({ setShowLogin }) => {
    return (
        <div className='imageFooter'>
            {/* Enlace a WhatsApp */}
            <a href="https://wa.me/+5492944211270" target="_blank" rel="noopener noreferrer">
                <img
                    className='imageFooter2'
                    alt='whatsapp'
                    src={whats}
                    title="¡Contáctanos por WhatsApp!"
                /> Contactame por whatsapp
            </a>

            {/* Enlace a Instagram */}
            <a href="https://www.instagram.com/huma.brc" target="_blank" rel="noopener noreferrer">
                <img
                    className='imageFooter2'
                    alt='instagram'
                    src={insta}
                    title="Síguenos en Instagram"
                />Seguime en Instagram
            </a>

            {/* Enlace a la página de contacto */}
            <a href="/contact" target="_blank" rel="noopener noreferrer">
                <img
                    className='imageFooter2' 
                    alt='contacto'
                    src={contact}
                    title="Contáctanos"
                />Escribime por pedido personalizados
            </a>

            {/* Botón para mostrar el login */}
      
        </div>
    );
};

export default Footer;
