import { useState } from "react";

const Cart = ({ cartItems, setCartItems }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [showPopup, setShowPopup] = useState(false);

    if (!Array.isArray(cartItems)) {
        cartItems = [];
    }

    const increaseQuantity = (index) => {
        const newCart = [...cartItems];
        newCart[index].cantidad += 1;
        setCartItems(newCart);
    };

    const decreaseQuantity = (index) => {
        const newCart = [...cartItems];
        if (newCart[index].cantidad > 1) {
            newCart[index].cantidad -= 1;
        } else {
            newCart.splice(index, 1);
        }
        setCartItems(newCart);
    };

    const getTotal = () => {
        return cartItems.reduce((total, item) => total + item.precio * item.cantidad, 0);
    };

    const clearCart = () => {
        setCartItems([]);
    };

    const handlePurchase = () => {
        // Crear un mensaje con todos los productos en el carrito
        const productosPedido = cartItems.map(item =>
            `${item.nombre} x${item.cantidad} - $${item.precio * item.cantidad}`).join("\n");

        // Calcular el total de la compra
        const total = cartItems.reduce((total, item) => total + (item.precio * item.cantidad), 0);

        // Crear el mensaje final para WhatsApp
        const mensaje = `¡Nuevo pedido!\n\n${productosPedido}\n\nTotal: $${total}`;

        // Enlace para abrir WhatsApp con el mensaje
        const url = `https://wa.me/542944895986?text=${encodeURIComponent(mensaje)}`;

        // Abrir WhatsApp
        window.open(url, "_blank");

        // Mostrar el popup de confirmación
        setShowPopup(true);
    };

    return (
        <>
            <div
                className="cart-icon "
                onClick={() => setIsOpen(true)}
                style={{
                    position: "fixed",
                    top: 50,
                    right: 30,
                    cursor: "pointer",
                    padding: "6px",
                    borderRadius: "10px",
                    width: '60px',
                    height: '10px',
                    marginTop:'10px',
                    paddingTop:'28px'
                }}
            >
                <p className="cartText">CARRITO</p>
                🛒 {cartItems.length > 0 && <span>({cartItems.reduce((acc, item) => acc + item.cantidad, 0)})</span>}
            </div>

            {isOpen && (
                <div
                    className="cart-fullscreen"
                    style={{
                        position: "fixed",
                        top: 0,
                        left: 0,
                        width: "100%",
                        height: "100vh",
                        backgroundColor: "rgba(0,0,0,0.8)",
                        color: "white",
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                        justifyContent: "center",
                        zIndex: 10,
                    }}
                >
                    <button
                        onClick={() => setIsOpen(false)}
                        style={{
                            position: "absolute",
                            top: 20,
                            right: 20,
                            backgroundColor: "red",
                            color: "white",
                            padding: "10px",
                            borderRadius: "5px",
                        }}
                    >
                        Cerrar
                    </button>
                    <h2>Carrito de Compras</h2>
                    {cartItems.length === 0 ? (
                        <p>El carrito está vacío</p>
                    ) : (
                        <div
                            style={{
                                maxHeight: "60vh", // Activa el scroll cuando hay muchos productos
                                overflowY: "auto",
                                width: "100%",
                                padding: "10px"
                            }}
                        >
                            {cartItems.map((item, index) => (
                                <div key={index} style={{ padding: "10px", borderBottom: "1px solid white" }}>
                                    <h4>{item.nombre}</h4>
                                    <p>Precio: ${item.precio}</p>
                                    <p>Cantidad: {item.cantidad}</p>
                                    <button className="masOmenos" onClick={() => decreaseQuantity(index)}>-</button>
                                    <button className="masOmenos" onClick={() => increaseQuantity(index)}>+</button>
                                </div>
                            ))}
                        </div>
                    )}
                 
                    <h3>Total: ${getTotal()}</h3>
                    <div className="totalCarrito">
                    <button
                        onClick={clearCart}
                        style={{
                            backgroundColor: "#d21",
                            color: "white",
                            padding: "10px",
                            borderRadius: "5px",
                            marginRight: "10px",
                            borderStyle: "none"
                        }}
                    >
                        VACIAR 🗑️
                    </button>
                    <button
                        onClick={handlePurchase}
                        style={{
                            backgroundColor: "green",
                            color: "white",
                            padding: "10px",
                            borderRadius: "5px",
                            marginRight: "10px",
                            borderStyle: "none"
                        }}
                    >
                        COMPRAR 🛍️
                    </button>
                    <button
                        onClick={() => setIsOpen(false)}
                        style={{
                            backgroundColor: "#007bff",
                            color: "white",
                            padding: "10px",
                            borderRadius: "5px",
                            borderStyle: "none"
                        }}
                    >
                        Seguir comprando 🛒
                    </button>
                </div>
                </div>
            )}

            
        </>
    );
};

export default Cart;

