import { useState, useEffect } from "react";
import { getDatabase, ref, set, get, update, remove } from "firebase/database";
import SubirImagen from "./SubirImagen";
import { database } from "./firebase";

const GuardarProducto = () => {
    const [productos, setProductos] = useState([]);
    const [productoSeleccionado, setProductoSeleccionado] = useState(null);
    const [nombre, setNombre] = useState("");
    const [precio, setPrecio] = useState("");
    const [stock, setStock] = useState("");
    const [descripcion, setDescripcion] = useState("");
    const [imageUrl, setImageUrl] = useState("");

    useEffect(() => {
        const db = getDatabase();
        const productsRef = ref(db, "productos/");
        get(productsRef).then((snapshot) => {
            if (snapshot.exists()) {
                setProductos(Object.entries(snapshot.val()));
            }
        });
    }, []);

    const guardarEnFirebase = () => {
        if (!nombre || !precio || !stock || !imageUrl || !descripcion) {
            alert("Completa todos los campos");
            return;
        }
        const db = getDatabase();
        const productRef = ref(db, `productos/${nombre}`);
        set(productRef, { nombre, precio, stock, descripcion, imageUrl })
            .then(() => alert("Producto guardado"))
            .catch((error) => alert("Error: " + error));
    };

    const seleccionarProducto = (id, producto) => {
        setProductoSeleccionado(id);
        setNombre(producto.nombre);
        setPrecio(producto.precio);
        setStock(producto.stock);
        setDescripcion(producto.descripcion);
        setImageUrl(producto.imageUrl);
    };

    const actualizarProducto = () => {
        if (!productoSeleccionado) return;
        const db = getDatabase();
        const productRef = ref(db, `productos/${productoSeleccionado}`);
        update(productRef, { nombre, precio, stock, descripcion, imageUrl })
            .then(() => alert("Producto actualizado"))
            .catch((error) => alert("Error: " + error));
    };

    // Función para eliminar producto e imagen
    const eliminarProducto = async (id, imageUrl) => {
        try {
            // Eliminar de Firebase Realtime Database
            const db = getDatabase();
            const productRef = ref(db, `productos/${id}`);
            await remove(productRef);

            // Obtener el public_id de la URL de la imagen (esto asume que la URL de Cloudinary sigue el formato estándar)
            const publicId = imageUrl.split('/').pop().split('.')[0];

            // Eliminar la imagen de Cloudinary
            const cloudinaryUrl = `https://api.cloudinary.com/v1_1/${process.env.REACT_APP_CLOUDINARY_CLOUD_NAME}/image/destroy`;
            const formData = new FormData();
            formData.append("public_id", publicId);
            formData.append("api_key", process.env.REACT_APP_CLOUDINARY_API_KEY);
            formData.append("api_secret", process.env.REACT_APP_CLOUDINARY_API_SECRET);

            const res = await fetch(cloudinaryUrl, {
                method: "POST",
                body: formData,
            });

            const data = await res.json();

            if (data.result === "ok") {
                alert("Producto y imagen eliminados con éxito");
            } else {
                alert("Error al eliminar la imagen en Cloudinary: " + data.error.message);
            }
        } catch (error) {
            console.error("Error al eliminar el producto o la imagen:", error);
            alert("Error al eliminar el producto o la imagen");
        }
    };

    return (
        <div className="ingresarProd">
            <h3>{productoSeleccionado ? "Editar Producto" : "Agregar Producto"}</h3>
            <input
                className="inputProd"
                type="text"
                placeholder="Nombre"
                value={nombre}
                onChange={(e) => setNombre(e.target.value)}
                disabled={!!productoSeleccionado}
            />
            <input
                className="inputProd precio"
                type="number"
                placeholder="Precio"
                value={precio}
                onChange={(e) => setPrecio(e.target.value)}
            />
            <input
                className="inputProd stock"
                type="number"
                placeholder="Stock"
                value={stock}
                onChange={(e) => setStock(e.target.value)}
            />
            <textarea
                className="inputProd"
                placeholder="Descripción"
                value={descripcion}
                onChange={(e) => setDescripcion(e.target.value)}
                rows="3"
            />
            <SubirImagen onUpload={setImageUrl} />
            {productoSeleccionado ? (
                <button className="login" onClick={actualizarProducto}>Actualizar Producto</button>
            ) : (
                <button className="login" onClick={guardarEnFirebase}>Guardar Producto</button>
            )}

            <h3>Productos Guardados</h3>
            <ul>
                {productos.map(([id, producto]) => (
                    <li key={id}>
                        {producto.nombre} - ${producto.precio}
                        <button className="login" onClick={() => seleccionarProducto(id, producto)}>Editar</button>
                        <button className="login" onClick={() => eliminarProducto(id, producto.imageUrl)}>Eliminar</button>
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default GuardarProducto;
